import{_ as e,c as t,a4 as n,o as i}from"./chunks/framework.BnpbgGx4.js";const o="/assets/langsim.CONYfkEV.png",r="/assets/T2Dllama.DGG_b6xn.png",s="/assets/yeLLowhaMMer.BCNZD5hS.png",f=JSON.parse('{"title":"2024 LLM Hackathon in Sci","description":"Excerpts from the 2024 LLM hackathon for materials science and chemistry.","frontmatter":{"date":"2025-02-17","title":"2024 LLM Hackathon in Sci","description":"Excerpts from the 2024 LLM hackathon for materials science and chemistry.","tags":["LLM","Science","Hackathon"],"lang":"en","blog":true,"majorTag":"Computing","titleColor":"red"},"headers":[],"relativePath":"StudyRec/20250217-2024LLMHackInSci.md","filePath":"StudyRec/20250217-2024LLMHackInSci.md"}'),l={name:"StudyRec/20250217-2024LLMHackInSci.md"};function c(m,a,g,h,d,u){return i(),t("div",null,a[0]||(a[0]=[n('<h1 id="_2024-large-language-model-llm-hackathon-for-applications-in-materials-science-and-chemistry" tabindex="-1"><div style="text-align:center;"><h1 style="font-size:2.5rem;font-weight:bold;">2024 Large Language Model (LLM) Hackathon for Applications in Materials Science and Chemistry</h1></div> <a class="header-anchor" href="#_2024-large-language-model-llm-hackathon-for-applications-in-materials-science-and-chemistry" aria-label="Permalink to &quot;&lt;div style=&quot;text-align: center;&quot;&gt;&lt;h1 style=&quot;font-size: 2.5rem; font-weight: bold&quot;&gt;2024 Large Language Model (LLM) Hackathon for Applications in Materials Science and Chemistry&lt;/h1&gt;&lt;/div&gt;&quot;">​</a></h1><p>I stumbled across this hackathon on large language models (LLMs) for applications in materials science and chemistry. I found it so interesting that I decided to document it. <a href="https://github.com/bocarsly-group/llm-hackathon-2024" target="_blank" rel="noreferrer">→</a></p><h2 id="areas" tabindex="-1">Areas <a class="header-anchor" href="#areas" aria-label="Permalink to &quot;Areas&quot;">​</a></h2><ol><li><strong>Molecular and Material Property Prediction</strong>: Using LLMs to predict the chemical and physical properties of molecules and materials, with a particular strength in low-data settings and by combining structured and unstructured data.</li><li><strong>Molecular and Material Design</strong>: Using LLMs to generate and optimize novel molecules and materials, including peptides, metal–organic frameworks, and environmentally friendly building materials.</li><li><strong>Automation and Novel Interfaces</strong>: Developing natural-language interfaces and automated workflows that simplify complex scientific tasks and make advanced tools and techniques easier for researchers to use. (This one is the most fun.)</li><li><strong>Scientific Communication and Education</strong>: Strengthening academic communication, automating the creation of educational content, and promoting learning in materials science and chemistry.</li><li><strong>Research Data Management and Automation</strong>: Streamlining the processing, organization, and management of scientific data through LLM-driven tools and multimodal agents. (This one interests me the most.)</li><li><strong>Hypothesis Generation and Evaluation</strong>: Using LLMs to generate, evaluate, and validate scientific hypotheses, often in combination with multiple AI agents and statistical methods.</li><li><strong>Knowledge Extraction and Reasoning</strong>: Extracting structured information from scientific literature and performing in-depth reasoning about chemical and materials science concepts through knowledge graphs and multimodal approaches. (This one is relatively mature.)</li></ol><h2 id="automated-workflows" tabindex="-1">Automated Workflows <a class="header-anchor" href="#automated-workflows" aria-label="Permalink to &quot;Automated Workflows&quot;">​</a></h2><h3 id="langsim→" tabindex="-1">LangSim<a href="http://jan-janssen.com/LangSim/" target="_blank" rel="noreferrer">→</a> <a class="header-anchor" href="#langsim→" aria-label="Permalink to &quot;LangSim[→](http://jan-janssen.com/LangSim/)&quot;">​</a></h3><div class="custom-image"><p><img src="'+o+'" alt="shap_interaction_matrix" loading="lazy"></p></div><p>The LangSim research agent is built on the LangChain package, implementing existing simulation workflows as LangChain agents.</p><p>Although I think this software has many strengths, it is difficult for an LLM to autonomously solve many simulation problems. It feels fine for the software to compute a few simple properties,</p><h3 id="t2dllama-harnessing-language-model-for-density-functional-theory-dft-parameter-suggestion→" tabindex="-1">T2Dllama: Harnessing Language Model for Density Functional Theory (DFT) Parameter Suggestion<a href="https://github.com/chiku-parida/T2Dllama" target="_blank" rel="noreferrer">→</a> <a class="header-anchor" href="#t2dllama-harnessing-language-model-for-density-functional-theory-dft-parameter-suggestion→" aria-label="Permalink to &quot;T2Dllama: Harnessing Language Model for Density Functional Theory (DFT) Parameter Suggestion[→](https://github.com/chiku-parida/T2Dllama)&quot;">​</a></h3><div class="custom-image"><p><img src="'+r+'" alt="shap_interaction_matrix" loading="lazy"></p></div><p>This one uses the retrieval augmented generation (RAG) technique <sup class="footnote-ref"><a href="#RAG" id="RAG">[1]</a></sup>, which is effectively connecting to a database (although some studies suggest that this is less effective than simply putting all the materials into a longer context).</p><h3 id="yellowhammer-a-multi-modal-tool-calling-agent-for-accelerated-research-data-management→" tabindex="-1">yeLLowhaMMer: A Multi-modal Tool-calling Agent for Accelerated Research Data Management<a href="https://github.com/datalab-org/yellowhammer" target="_blank" rel="noreferrer">→</a> <a class="header-anchor" href="#yellowhammer-a-multi-modal-tool-calling-agent-for-accelerated-research-data-management→" aria-label="Permalink to &quot;yeLLowhaMMer: A Multi-modal Tool-calling Agent for Accelerated Research Data Management[→](https://github.com/datalab-org/yellowhammer)&quot;">​</a></h3><p>Using LLMs to simplify and accelerate data-processing tasks, it takes free-form text and image instructions from users and carries out various complex scientific data management tasks.</p><div class="custom-image"><p><img src="'+s+'" alt="shap_interaction_matrix" loading="lazy"></p></div><p>For example, instruct the agent: &quot;Extract my 10 most recent sample entries and summarize the synthesis methods used.&quot; In this case, the agent will try to use the datalab API to write and execute Python code in order to query the user&#39;s samples in the datalab instance and write a human-readable summary. If the code it generates produces an error (or does not provide enough information), the agent can iteratively rewrite the program until the task is completed successfully.</p><section class="footnotes"><ol class="footnotes-list"><li id="RAG" class="footnote-item"><p> Yunfan Gao, Yun Xiong, Xinyu Gao, Kangxiang Jia, Jinliu Pan, Yuxi Bic, Yi Dai, Jiawei Sun, Meng Wang, and Haofen Wang, “Retrieval-Augmented Generation for Large Language Models: A Survey”, <a href="https://doi.org/10.48550/arXiv.2312.10997" target="_blank">https://doi.org/10.48550/arXiv.2312.10997</a>. <a href="#fnRAG" class="footnote-backref">↩</a></p></li></ol></section>',17)]))}const y=e(l,[["render",c]]);export{f as __pageData,y as default};
